BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='30s';
SELECT jsonb_build_object(
'ledger',(SELECT jsonb_agg(jsonb_build_object('name',migration_name,'checksum',checksum,'finished',finished_at IS NOT NULL,'rolledBack',rolled_back_at IS NOT NULL) ORDER BY started_at) FROM public."_prisma_migrations"),
'metadata',jsonb_build_object('database',current_database(),'serverVersion',current_setting('server_version'),'publicTables',(SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p')),'applied',(SELECT count(*) FROM public."_prisma_migrations" WHERE finished_at IS NOT NULL AND rolled_back_at IS NULL),'unfinished',(SELECT count(*) FROM public."_prisma_migrations" WHERE finished_at IS NULL AND rolled_back_at IS NULL),'stage28Entries',(SELECT count(*) FROM public."_prisma_migrations" WHERE migration_name='20261003120000_customer_stage_one')),
'counts',jsonb_build_object('clients',(SELECT count(*) FROM public."Client"),'bookings',(SELECT count(*) FROM public."Booking"),'linkedClients',(SELECT count(*) FROM public."Client" WHERE "userId" IS NOT NULL)),
'clientSessions',(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) FROM (SELECT usename,application_name,state,count(*) AS sessions,count(*) FILTER(WHERE xact_start IS NOT NULL) AS transactions FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() AND backend_type='client backend' GROUP BY usename,application_name,state ORDER BY usename,application_name,state) s),
'preparedTransactions',(SELECT count(*) FROM pg_prepared_xacts WHERE database=current_database()),
'extensions',(SELECT jsonb_agg(jsonb_build_object('name',e.extname,'schema',n.nspname,'version',e.extversion) ORDER BY e.extname) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace)
) AS precheck;
COMMIT;

BEGIN READ ONLY; SET LOCAL statement_timeout='30s';
SELECT jsonb_build_object(
'roles',(SELECT jsonb_agg(jsonb_build_object('role',rolname,'super',rolsuper,'inherit',rolinherit,'createDb',rolcreatedb,'createRole',rolcreaterole,'login',rolcanlogin,'replication',rolreplication,'bypassRls',rolbypassrls) ORDER BY rolname) FROM pg_roles WHERE rolname IN ('kortek_migrator','kortek_runtime')),
'membershipCount',(SELECT count(*) FROM pg_auth_members WHERE member IN ('kortek_migrator'::regrole,'kortek_runtime'::regrole)),
'otherRoleDml',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'writeTables',(SELECT count(*) FROM pg_tables t WHERE t.schemaname='public' AND (has_table_privilege(r.rolname,format('%I.%I',t.schemaname,t.tablename),'INSERT') OR has_table_privilege(r.rolname,format('%I.%I',t.schemaname,t.tablename),'UPDATE') OR has_table_privilege(r.rolname,format('%I.%I',t.schemaname,t.tablename),'DELETE')))) ORDER BY r.rolname) FROM pg_roles r WHERE r.rolname IN ('anon','authenticated','authenticator','service_role','pgbouncer')),
'activeClientTransactions',(SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() AND backend_type='client backend' AND (state <> 'idle' OR xact_start IS NOT NULL)),
'pgCronInstalled',EXISTS(SELECT 1 FROM pg_extension WHERE extname='pg_cron')
) AS writers;
COMMIT;

